import{_ as e,o as a,c as t,a5 as i}from"./chunks/framework.D47SInms.js";const k=JSON.parse('{"title":"RBH","description":"","frontmatter":{},"headers":[],"relativePath":"rbh-public-README.md","filePath":"rbh-public-README.md","lastUpdated":1791600043000}'),o={name:"rbh-public-README.md"};function n(r,s,h,l,p,d){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="rbh" tabindex="-1">RBH <a class="header-anchor" href="#rbh" aria-label="Permalink to &quot;RBH&quot;">​</a></h1><p>Rainbow Robotics humanoid (RBH_SCH_v1): simulate the robot on your PC, and control it with the C++ SDK — the same binaries and the same DDS interface the real robot runs.</p><p>The binaries are built for <strong>Ubuntu 24.04</strong>, the robot PC, and the Docker image matches it, so nothing of them has to fit your PC. The SDK example is built for <strong>Ubuntu 22.04</strong>, the operator PC — it also runs on 24.04.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bin-x86_64/     Motion, Network, Daemon, Humanoid, MuJoCo, and their libraries (Ubuntu 24.04)</span></span>
<span class="line"><span>resources/rbh/  the simulator&#39;s MuJoCo model (mjcf), meshes and URDF</span></span>
<span class="line"><span>rb_sdk/         the SDK, as source: the library (cpp/rb_sdk_cpp) and rbh_low_level (cpp/example)</span></span>
<span class="line"><span>scripts/        sim.bash + Dockerfile — the simulation</span></span></code></pre></div><p>The robot&#39;s update package is not in the tree: it is the release asset <code>RBH-&lt;tag&gt;.rbh</code> (sealed; <code>.sha256</code> next to it). Robots with internet take it from the dashboard&#39;s Update button; otherwise download it and use <strong>Install a file…</strong> on the same card.</p><h2 id="simulate-in-docker" tabindex="-1">Simulate, in Docker <a class="header-anchor" href="#simulate-in-docker" aria-label="Permalink to &quot;Simulate, in Docker&quot;">​</a></h2><p>No compiler or system libraries needed on your PC — the image carries what the binaries link against (GLFW, GL, OpenCV, ...):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # the simulated robot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --shell</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # a shell in the image instead, the tree mounted</span></span></code></pre></div><p><code>Motion --sim --rbh</code> brings up Network and the Daemon — the state topics and the command link — and <code>Mujoco --rbh</code> is the simulated robot. The first run builds the image (a few minutes). The simulator draws on your X server; if the window does not appear, allow local connections once with <code>xhost +local:docker</code>. Ctrl-C stops everything, and the logs are under <code>log/sim-docker/</code>.</p><p>Shared memory stays inside the container, so a simulation cannot disturb your PC. DDS uses host networking, so the SDK example below reaches the simulated robot exactly as it reaches a real one.</p><h2 id="operator-ui" tabindex="-1">Operator UI <a class="header-anchor" href="#operator-ui" aria-label="Permalink to &quot;Operator UI&quot;">​</a></h2><p>The robot serves a dashboard on <strong>http://&lt;robot&gt;:8080</strong> (<strong>localhost</strong> for the simulation), user <strong><code>rb</code></strong>, password <strong><code>rainbow2026</code></strong>.</p><p>Its Humanoid pages show joint state, plots and a joystick page.</p><h2 id="control-it-from-your-pc-sdk" tabindex="-1">Control it from your PC (SDK) <a class="header-anchor" href="#control-it-from-your-pc-sdk" aria-label="Permalink to &quot;Control it from your PC (SDK)&quot;">​</a></h2><p><code>rbh_low_level</code> reads the robot&#39;s state and sends joint references over DDS: home pose, a task-space squat, and the walking policy driven by a gamepad.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb_sdk/cpp/example</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docker/run.bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # build -&gt; bin-x86_64/ (--arch arm64 for an aarch64 PC)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/deploy.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or run bin-&lt;arch&gt;/rbh_low_level here</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbh_low_level</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">network-interfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Keys: <code>x</code> home pose, <code>z</code> zero pose, <code>s</code> squat, <code>p</code> policy (once to take the ready pose, again to start), <code>Backspace</code> reset the simulator, <code>r</code> release the joints, <code>q</code> quit. The robot and policy it uses come from <code>src/rbh/default_config.yml</code>.</p><p>The policy walks on gamepad commands. They come from the robot by default; <code>--joystick</code> reads a pad plugged into this PC instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbh_low_level</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">network-interfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --joystick</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # /dev/input/js0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbh_low_level</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">network-interfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --joystick</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/input/js1</span></span></code></pre></div><p>Left stick walks, right stick turns, the D-pad raises and lowers the forward speed limit, and the right trigger lowers the torso if the policy was trained for it.</p><p><code>Backspace</code> does what MuJoCo&#39;s own Backspace does — the robot returns to its home pose on the floor. Useful after a fall: hold a pose with <code>x</code> first, then reset, and it stays standing. On a real robot nothing listens to it.</p><p>The simulated robot has no on-robot walking controller in this release, so it stays where the references put it until <code>rbh_low_level</code> drives it.</p><h2 id="update-a-robot" tabindex="-1">Update a robot <a class="header-anchor" href="#update-a-robot" aria-label="Permalink to &quot;Update a robot&quot;">​</a></h2><p>Open the robot&#39;s dashboard — <code>http://&lt;robot&gt;:8080</code>, user <code>rb</code>, password <code>rainbow2026</code> — and on <strong>Overview → Software</strong> press <strong>Update</strong>. The page downloads the latest release, hands it to the robot, and the robot installs it and restarts its software; the page reconnects when it is back. Without internet at the robot, download <code>RBH-&lt;version&gt;.rbh</code> from this repository&#39;s releases anywhere and use <strong>Install a file…</strong> on the same card. The robot installs only these sealed <code>.rbh</code> packages; a tarball or an edited file is refused.</p>`,24)])])}const b=e(o,[["render",n]]);export{k as __pageData,b as default};
